def first_unique(nums):
    seen = set()
    for n in nums:
        if n in seen:
            return n
        seen.add(n)
    return -1

def max_product_pair(nums):
    nums = sorted(nums)
    return max(nums[0] * nums[1], nums[-1] * nums[-2])

def count_good_pairs(nums):
    count, freq = 0, {}
    for n in nums:
        count += freq.get(n, 0)
        freq[n] = freq.get(n, 0) + 1
    return count

def first_negative_in_window(arr, k):
    from collections import deque
    dq = deque()
    res = []
    for i in range(len(arr)):
        if arr[i] < 0:
            dq.append(i)
        while dq and dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            res.append(arr[dq[0]] if dq else 0)
    return res

def max_consecutive_ones(nums):
    best = cur = 0
    for n in nums:
        cur = cur + 1 if n else 0
        if cur > best:
            best = cur
    return best

def max_consecutive_ones_iii(nums, k):
    left = 0
    zeros = 0
    best = 0
    for right in range(len(nums)):
        if nums[right] == 0:
            zeros += 1
        while zeros > k:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

def longest_substring_k_distinct(s, k):
    if k <= 0 or not s:
        return 0
    counts = {}
    left = 0
    best = 0
    for right in range(len(s)):
        counts[s[right]] = counts.get(s[right], 0) + 1
        while len(counts) > k:
            counts[s[left]] -= 1
            if counts[s[left]] == 0:
                del counts[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

def sliding_window_maximum(nums, k):
    from collections import deque
    dq = deque()
    res = []
    for i in range(len(nums)):
        while dq and nums[dq[-1]] <= nums[i]:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

def count_zero_triplets(nums):
    nums = sorted(nums)
    n = len(nums)
    res = 0
    for i in range(n):
        if i and nums[i] == nums[i - 1]:
            continue
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = nums[i] + nums[lo] + nums[hi]
            if s == 0:
                res += 1
                while lo < hi and nums[lo] == nums[lo + 1]:
                    lo += 1
                while lo < hi and nums[hi] == nums[hi - 1]:
                    hi -= 1
                lo += 1
                hi -= 1
            elif s < 0:
                lo += 1
            else:
                hi -= 1
    return res

def max_container_area(heights):
    lo, hi = 0, len(heights) - 1
    best = 0
    while lo < hi:
        best = max(best, min(heights[lo], heights[hi]) * (hi - lo))
        if heights[lo] < heights[hi]:
            lo += 1
        else:
            hi -= 1
    return best

def sort_colors(nums):
    nums[:] = sorted(nums)
    return nums

def trap_rain_water(heights):
    lo, hi = 0, len(heights) - 1
    lmax = rmax = 0
    water = 0
    while lo <= hi:
        if lmax <= rmax:
            if heights[lo] >= lmax:
                lmax = heights[lo]
            else:
                water += lmax - heights[lo]
            lo += 1
        else:
            if heights[hi] >= rmax:
                rmax = heights[hi]
            else:
                water += rmax - heights[hi]
            hi -= 1
    return water

def count_zero_quads(nums, target):
    nums = sorted(nums)
    n = len(nums)
    res = 0
    for i in range(n):
        if i and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, n):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            lo, hi = j + 1, n - 1
            while lo < hi:
                s = nums[i] + nums[j] + nums[lo] + nums[hi]
                if s == target:
                    res += 1
                    while lo < hi and nums[lo] == nums[lo + 1]:
                        lo += 1
                    while lo < hi and nums[hi] == nums[hi - 1]:
                        hi -= 1
                    lo += 1
                    hi -= 1
                elif s < target:
                    lo += 1
                else:
                    hi -= 1
    return res

def search_rotated_dups(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] == nums[mid] == nums[hi]:
            lo += 1
            hi -= 1
        elif nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

def median_two_sorted(a, b):
    merged = sorted(a + b)
    m = len(merged)
    if m == 0:
        return 0.0
    if m % 2 == 1:
        return float(merged[m // 2])
    return (merged[m // 2 - 1] + merged[m // 2]) / 2.0

def two_sum(nums, target):
    seen = {}
    for i, v in enumerate(nums):
        other = target - v
        if other in seen:
            return sorted([seen[other], i])
        seen[v] = i
    return []

def majority_element(nums):
    cand, cnt = None, 0
    for x in nums:
        if cnt == 0:
            cand = x
        cnt += 1 if x == cand else -1
    return cand

def unique_occurrences(arr):
    from collections import Counter
    c = Counter(arr)
    return len(c.values()) == len(set(c.values()))

def jewels_in_stones(jewels, stones):
    s = set(jewels)
    return sum(1 for ch in stones if ch in s)

def group_anagrams(words):
    from collections import defaultdict
    m = defaultdict(list)
    for w in words:
        m["".join(sorted(w))].append(w)
    return sorted((sorted(v) for v in m.values()), key=lambda g: g[0])

def longest_consecutive(nums):
    s = set(nums)
    best = 0
    for x in s:
        if x - 1 not in s:
            cur, ln = x, 1
            while cur + 1 in s:
                cur += 1
                ln += 1
            best = max(best, ln)
    return best

def top_k_frequent(nums, k):
    from collections import Counter
    return [v for v, _ in Counter(nums).most_common(k)]

def first_missing_positive(nums):
    s = set(nums)
    i = 1
    while i in s:
        i += 1
    return i

def max_frequency_after_k(nums, k):
    nums = sorted(nums)
    best, total, left = 0, 0, 0
    for right in range(len(nums)):
        total += nums[right]
        while nums[right] * (right - left + 1) - total > k:
            total -= nums[left]
            left += 1
        best = max(best, right - left + 1)
    return best

def valid_anagram(s, t):
    from collections import Counter
    return Counter(s) == Counter(t)

def longest_common_prefix(words):
    if not words:
        return ""
    p = words[0]
    for w in words[1:]:
        while not w.startswith(p):
            p = p[:-1]
            if not p:
                return ""
    return p

def first_unique_char(s):
    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1:
            return i
    return -1

def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    arr = list(s)
    i, j = 0, len(arr) - 1
    while i < j:
        while i < j and arr[i] not in vowels:
            i += 1
        while i < j and arr[j] not in vowels:
            j -= 1
        arr[i], arr[j] = arr[j], arr[i]
        i += 1
        j -= 1
    return "".join(arr)

def run_length_compress(s):
    if not s:
        return ""
    out = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            out.append(s[i - 1] + str(count))
            count = 1
    out.append(s[-1] + str(count))
    return "".join(out)

def count_and_say(n):
    s = "1"
    for _ in range(n - 1):
        out = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            out.append(str(j - i) + s[i])
            i = j
        s = "".join(out)
    return s

def max_sum_fixed_k(nums, k):
    if k <= 0 or k > len(nums):
        return None
    cur = sum(nums[:k])
    best = cur
    for i in range(k, len(nums)):
        cur += nums[i] - nums[i - k]
        best = max(best, cur)
    return best

def min_swaps_group_ones(nums):
    ones = nums.count(1)
    if ones <= 1:
        return 0
    cur = sum(nums[:ones])
    best = cur
    for i in range(ones, len(nums)):
        cur += nums[i] - nums[i - ones]
        best = max(best, cur)
    return ones - best

def shortest_substr_all_distinct(s):
    from collections import defaultdict
    need = set(s)
    if not need:
        return 0
    want = len(need)
    seen = defaultdict(int)
    have, left, best = 0, 0, len(s) + 1
    for right, ch in enumerate(s):
        seen[ch] += 1
        if seen[ch] == 1:
            have += 1
        while have == want:
            best = min(best, right - left + 1)
            lc = s[left]
            seen[lc] -= 1
            if seen[lc] == 0:
                have -= 1
            left += 1
    return best

def search_insert_position(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def peak_index_mountain(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[mid + 1]:
            hi = mid
        else:
            lo = mid + 1
    return lo
